/*
	VIOC_fire_orders.sqf - agregado por tools/vio_build.py (parche fire_orders; copia configurada, no es del autor de la
	mision). Fuente: work/v6_build/fire_orders/.

	Ordenes de fuego a la IA de TU grupo: el artillero dispara solo al punto o al objetivo que marques (no hace falta
	decirle "fuego").
	  - "ORDEN: Atacar donde miro": el punto u objetivo bajo tu mira (centro de la pantalla). Si vas en un vehiculo con
	    artillero IA de tu grupo (tu de jefe, conductor o pasajero), ese vehiculo; si no, los vehiculos de tu grupo que
	    tengas seleccionados (F2, F3...) o, sin seleccion, todos los de fuego directo de tu grupo.
	  - "ORDEN: Atacar punto (mapa)": abre el mapa con un panel a la derecha: clic = punto; eliges el vehiculo (o "todos
	    los de fuego directo"), la municion y los disparos (artilleria) o los segundos de fuego (fuego directo).
	  - "Artillero: disparar a discrecion (ON/OFF)": la tripulacion IA de tu vehiculo en modo de combate ROJO.
	Fuego directo (M1128 MGS, M1, BMP, HMMWV...): con un objetivo enemigo, doTarget + doFire; con un punto (suelo, casa,
	vehiculo vacio), doWatch + doSuppressiveFire (+ suppressFor) durante N s, repetido cada 4 s. Arma y municion por la
	cabeza de guerra (CfgAmmo warheadName): punto/casa/infanteria = HE (en el M1128: M393A3 HEP del canon de 105 mm),
	blindado = AP (M900) o HEAT; se carga con loadMagazine y selectWeapon (como LAMBS). Si el canon no dispara en 8 s,
	se fuerza el disparo (forceWeaponFire) cuando esta apuntado al punto (hasta 1200 m, con correccion de caida).
	Artilleria (artilleryScanner o municion de artilleria: M109, HIMARS, M270, 2S1, 2S3, BM-21, morteros): municion
	real del vehiculo (getArtilleryAmmo, HE primero), 1/3/5/10 disparos, alcance (inRangeOfArtillery) y tiempo de
	llegada (getArtilleryETA); doArtilleryFire (y commandArtilleryFire si a los 12 s no empezo). Marca el punto en tu
	mapa y avisa al disparar y al terminar.
	Mientras dura la orden: el modo de combate de la tripulacion sube a AMARILLO si estaba en mantener fuego, el grupo
	pasa de DESCUIDADO/SEGURO a ALERTA y LAMBS no manda en la tripulacion (lambs_danger_disableAI); al final se devuelve todo.
	Seguridad: no dispara si hay tropas propias (no civiles) a menos de 50 m (fuego directo) / 150 m (artilleria).
	Solo la IA de tu grupo (nunca la de otro jugador). La orden corre donde es local el artillero (remoteExecCall al
	artillero si no es de esta maquina). Ambos bandos, cualquier mapa.
	Parametros de lobby VIOC_FIRE_ORDERS, VIOC_FIRE_ORDERS_TIME, VIOC_FIRE_ORDERS_ARTY (y respeta ARTILLERY: Setup).
	Consola (Ejecucion local): [] spawn VIOC_FO_fnc_open;   [] spawn VIOC_FO_fnc_quick;   hint (call VIOC_FO_fnc_status);
*/
if ((missionNamespace getVariable ["VIOC_FIRE_ORDERS", 1]) <= 0) exitWith {};

VIOC_FO_SECS = missionNamespace getVariable ["VIOC_FIRE_ORDERS_TIME", 20];
if !(VIOC_FO_SECS isEqualType 0) then {VIOC_FO_SECS = 20};
VIOC_FO_SECS = (VIOC_FO_SECS max 5) min 120;
VIOC_FO_ARTY = missionNamespace getVariable ["VIOC_FIRE_ORDERS_ARTY", 1];
if !(VIOC_FO_ARTY isEqualType 0) then {VIOC_FO_ARTY = 1};
VIOC_FO_SAFE_DIRECT = 50;	//--- m: tropas propias cerca del punto = no dispara (fuego directo)
VIOC_FO_SAFE_ARTY = 150;	//--- m: lo mismo para artilleria
VIOC_FO_FORCE_MAX = 1200;	//--- m: hasta donde se fuerza el disparo del canon si el artillero no dispara solo

//=====================================================================================================================
//--- Comun (todas las maquinas: la orden corre donde es local el artillero)
//=====================================================================================================================

//--- 0 = artilleria apagada, 1 = sin espera, 2 = con la espera de la mision (CTI_ARTILLERY_TIMEOUT). "ARTILLERY: Setup" = Disabled la apaga.
VIOC_FO_fnc_artyMode = {
	private _m = VIOC_FO_ARTY;
	if ((missionNamespace getVariable ["CTI_ARTILLERY_SETUP", 15000]) isEqualTo -2) then {_m = 0};
	_m
};

//--- Vehiculo de artilleria: artilleryScanner en su config o algun cargador con municion de artilleria (artilleryLock).
VIOC_FO_fnc_isArty = {
	params ["_v"];
	private _k = "VIOC_FO_ART_" + typeOf _v;
	private _r = missionNamespace getVariable _k;
	if (isNil "_r") then {
		_r = (getNumber (configOf _v >> "artilleryScanner")) > 0;
		if (!_r) then {
			{
				if ((getNumber (configFile >> "CfgAmmo" >> (getText (configFile >> "CfgMagazines" >> (_x select 0) >> "ammo")) >> "artilleryLock")) > 0) exitWith {_r = true};
			} forEach (magazinesAllTurrets _v);
		};
		missionNamespace setVariable [_k, _r];
	};
	_r
};

//--- [cargador] -> [warheadName en mayusculas, es metralla (canister), hit + indirectHit, initSpeed]
VIOC_FO_fnc_ammoInfo = {
	params ["_m"];
	private _k = "VIOC_FO_AM_" + _m;
	private _r = missionNamespace getVariable _k;
	if (isNil "_r") then {
		private _ca = configFile >> "CfgAmmo" >> (getText (configFile >> "CfgMagazines" >> _m >> "ammo"));
		private _nm = toLower (getText (configFile >> "CfgMagazines" >> _m >> "displayName"));
		private _sub = getText (_ca >> "submunitionAmmo");
		private _tt = getNumber (_ca >> "triggerTime");
		private _can = ((_nm find "canister") >= 0) || {(_nm find "flechette") >= 0} || {(_sub != "") && {(getNumber (_ca >> "triggerOnImpact")) == 0} && {_tt > 0} && {_tt < 0.2}};
		_r = [toUpper (getText (_ca >> "warheadName")), _can, (getNumber (_ca >> "hit")) + (getNumber (_ca >> "indirectHit")), getNumber (configFile >> "CfgMagazines" >> _m >> "initSpeed")];
		missionNamespace setVariable [_k, _r];
	};
	_r
};

//--- Puntaje de un cargador para el tipo de blanco (menor = mejor). Tipos: HE (punto, casa), MAN, SOFT, ARMOR.
VIOC_FO_fnc_score = {
	params ["_info", "_kind"];
	_info params ["_wh", "_can"];
	private _he = (_wh == "HE") && {!_can};
	private _heat = _wh in ["HEAT", "TANDEMHEAT"];
	private _ap = _wh == "AP";
	switch (_kind) do {
		case "ARMOR": {if (_ap) then {0} else {if (_wh == "TANDEMHEAT") then {0.5} else {if (_heat) then {1} else {if (_he) then {3} else {5}}}}};
		case "SOFT": {if (_heat) then {0} else {if (_he) then {1} else {if (_ap) then {2} else {3}}}};
		case "MAN": {if (_he) then {0} else {if (_can) then {1} else {if (_heat) then {1.5} else {if (_ap) then {4} else {2}}}}};
		default {if (_he) then {0} else {if (_heat) then {1} else {if (_can) then {3} else {if (_ap) then {4} else {5}}}}};
	}
};

//--- [vehiculo, torreta, tipo] -> [arma, boca, cargador, puntaje, poder]: el mejor cargador que tiene la torreta para ese blanco.
VIOC_FO_fnc_pickWeapon = {
	params ["_v", "_tp", "_kind"];
	private _have = _v magazinesTurret _tp;
	private _best = ["", "", "", 99, -1];
	{
		private _w = _x;
		private _lw = toLower _w;
		private _cw = configFile >> "CfgWeapons" >> _w;
		private _skip = ((["smoke", "horn", "laserdesignator", "flare", "dummy"] findIf {(_lw find _x) >= 0}) >= 0) || {(toLower (getText (_cw >> "simulation"))) == "cmlauncher"};
		if (!_skip) then {
			{
				private _mz = _x;
				private _mzc = if (_mz == "this") then {_cw} else {_cw >> _mz};
				private _compat = (getArray (_mzc >> "magazines")) apply {toLower _x};
				{
					if ((toLower _x) in _compat) then {
						private _info = [_x] call VIOC_FO_fnc_ammoInfo;
						private _sc = [_info, _kind] call VIOC_FO_fnc_score;
						if ((_sc < (_best select 3)) || {(_sc == (_best select 3)) && {(_info select 2) > (_best select 4)}}) then {
							_best = [_w, if (_mz == "this") then {_w} else {_mz}, _x, _sc, _info select 2];
						};
					};
				} forEach _have;
			} forEach (getArray (_cw >> "muzzles"));
		};
	} forEach (_v weaponsTurret _tp);
	_best
};

//--- Tipo de blanco de un objeto.
VIOC_FO_fnc_kindOf = {
	params ["_o"];
	if (_o isKindOf "CAManBase") exitWith {"MAN"};
	if ((_o isKindOf "Tank") || {_o isKindOf "Wheeled_APC_F"}) exitWith {"ARMOR"};
	"SOFT"
};

//--- [objeto, bando] -> true si esta vivo y tiene gente enemiga de ese bando.
VIOC_FO_fnc_isEnemy = {
	params ["_o", "_side"];
	if (isNull _o || {!alive _o}) exitWith {false};
	private _crew = if (_o isKindOf "CAManBase") then {[_o]} else {(crew _o) select {alive _x}};
	if (count _crew == 0) exitWith {false};
	(_side getFriend (side group (_crew select 0))) < 0.6
};

//--- Nombre corto del vehiculo para los avisos: "[3] M1128 MGS".
VIOC_FO_fnc_vName = {
	params ["_v"];
	private _n = getText (configOf _v >> "displayName");
	if (_n == "") then {_n = typeOf _v};
	private _d = "";
	if (!isNil "CTI_CL_FNC_GetAIDigit" && {!isNull (gunner _v)}) then {_d = (gunner _v) call CTI_CL_FNC_GetAIDigit};
	if (_d isEqualType "" && {_d != ""} && {_d != "0"}) then {format ["[%1] %2", _d, _n]} else {_n}
};

//--- Respuesta para el jugador que dio la orden (en su maquina).
VIOC_FO_fnc_tell = {
	params ["_req", "_text", ["_v", objNull], ["_end", false], ["_keep", 0]];
	if (isNull _req) exitWith {};
	if (local _req) then {
		if (!isNil "VIOC_FO_fnc_note") then {[_text, _v, _end, _keep] call VIOC_FO_fnc_note};
	} else {
		[_text, _v, _end, _keep] remoteExecCall ["VIOC_FO_fnc_note", _req];
	};
};

//--- Cuenta los disparos del vehiculo (evento Fired local; uno por vehiculo).
VIOC_FO_fnc_firedEH = {
	params ["_v"];
	if (_v getVariable ["vioc_fo_eh", false]) exitWith {};
	_v setVariable ["vioc_fo_eh", true];
	_v addEventHandler ["Fired", {
		params ["_u", "_w", "", "", "", "_m"];
		_u setVariable ["vioc_fo_nAll", (_u getVariable ["vioc_fo_nAll", 0]) + 1];
		if (_w == (_u getVariable ["vioc_fo_mainW", "-"])) then {_u setVariable ["vioc_fo_nMain", (_u getVariable ["vioc_fo_nMain", 0]) + 1]};
		if (_m == (_u getVariable ["vioc_fo_watchMag", "-"])) then {_u setVariable ["vioc_fo_nMag", (_u getVariable ["vioc_fo_nMag", 0]) + 1]};
	}];
};

//--- Antes de una orden: sube el modo de combate (si estaba en mantener fuego), saca de DESCUIDADO/SEGURO y apaga LAMBS en la
//--- tripulacion IA local. Guarda lo anterior una sola vez (una orden nueva sobre el mismo vehiculo lo reutiliza).
VIOC_FO_fnc_prep = {
	params ["_v"];
	private _id = (_v getVariable ["vioc_fo_job", 0]) + 1;
	_v setVariable ["vioc_fo_job", _id];
	if (isNil {_v getVariable "vioc_fo_saved"}) then {
		private _sv = [];
		{
			if (alive _x && {!isPlayer _x} && {local _x}) then {
				private _m = unitCombatMode _x;
				private _up = "";
				if (_m in ["BLUE", "GREEN", "WHITE"]) then {_x setUnitCombatMode "YELLOW"; _up = "YELLOW"};
				private _lb = false;
				if !(_x getVariable ["lambs_danger_disableAI", false]) then {_x setVariable ["lambs_danger_disableAI", true]; _lb = true};
				_sv pushBack [_x, _m, _up, _lb];
			};
		} forEach (crew _v);
		private _g = group (gunner _v);
		private _b = "";
		private _bh = behaviour (gunner _v);
		if (!isNull _g && {local _g} && {_bh in ["CARELESS", "SAFE"]}) then {_g setBehaviour "AWARE"; _b = _bh};
		_v setVariable ["vioc_fo_saved", [_sv, _g, _b]];
	};
	_id
};

//--- Despues de la orden _id: devuelve lo que se cambio (solo si no llego otra orden mas nueva al mismo vehiculo).
VIOC_FO_fnc_restore = {
	params ["_v", "_id"];
	if ((_v getVariable ["vioc_fo_job", 0]) != _id) exitWith {};
	private _s = _v getVariable "vioc_fo_saved";
	_v setVariable ["vioc_fo_saved", nil];
	if (isNil "_s") exitWith {};
	_s params ["_sv", "_g", "_b"];
	{
		_x params ["_u", "_m", "_up", "_lb"];
		if (!isNull _u) then {
			if (_up != "" && {(unitCombatMode _u) == _up}) then {_u setUnitCombatMode _m};
			if (_lb) then {_u setVariable ["lambs_danger_disableAI", nil]};
		};
	} forEach _sv;
	if (_b != "" && {!isNull _g} && {local _g} && {(behaviour (leader _g)) == "AWARE"}) then {_g setBehaviour _b};
};

//--- [vehiculo, arma, artillero, punto ASL] -> el arma apunta al punto (2,5 grados en horizontal y no hacia el suelo de delante).
VIOC_FO_fnc_aimed = {
	params ["_v", "_w", "_g", "_p"];
	private _wd = _v weaponDirection _w;
	private _to = (eyePos _g) vectorFromTo _p;
	private _a = ((_wd select 0) atan2 (_wd select 1)) - ((_to select 0) atan2 (_to select 1));
	_a = ((_a + 540) mod 360) - 180;
	(abs _a < 2.5) && {(_wd select 2) > ((_to select 2) - 0.05)}
};

//--- Fuego directo (corre con spawn donde es local el artillero).
VIOC_FO_fnc_jobDirect = {
	params ["_v", "", "_pA", "_o", "", "", "_secs", "_req"];
	private _nm = [_v] call VIOC_FO_fnc_vName;
	private _id = [_v] call VIOC_FO_fnc_prep;
	private _g = gunner _v;
	private _tp = (assignedVehicleRole _g) param [1, [0]];
	if !(_tp isEqualType []) then {_tp = [0]};
	private _enemy = [_o, side group _g] call VIOC_FO_fnc_isEnemy;
	private _kind = if (_enemy) then {[_o] call VIOC_FO_fnc_kindOf} else {"HE"};
	private _pick = [_v, _tp, _kind] call VIOC_FO_fnc_pickWeapon;
	_pick params ["_w", "_mz", "_mg"];
	if (_w != "") then {
		if (_mg != "" && {((weaponState [_v, _tp, _mz]) param [3, ""]) != _mg}) then {_v loadMagazine [_tp, _w, _mg]};
		_g selectWeapon _mz;
	};
	[_v] call VIOC_FO_fnc_firedEH;
	_v setVariable ["vioc_fo_mainW", _w];
	private _n0 = _v getVariable ["vioc_fo_nMain", 0];
	private _a0 = _v getVariable ["vioc_fo_nAll", 0];
	//--- jefe IA con arma propia (p. ej. la M2 del jefe del M1128): tambien barre el punto
	private _c = commander _v;
	private _cm = objNull;
	if (!isNull _c && {!(_c isEqualTo _g)} && {alive _c} && {!isPlayer _c} && {local _c}) then {
		private _ctp = (assignedVehicleRole _c) param [1, []];
		if (_ctp isEqualType [] && {count _ctp > 0} && {(([_v, _ctp, "MAN"] call VIOC_FO_fnc_pickWeapon) select 0) != ""}) then {_cm = _c};
	};
	private _rt = 0;
	private _spd = 800;
	if (_w != "") then {
		_rt = getNumber (configFile >> "CfgWeapons" >> _w >> "reloadTime");
		_spd = getNumber (configFile >> "CfgMagazines" >> _mg >> "initSpeed");
		private _wi = getNumber (configFile >> "CfgWeapons" >> _w >> "initSpeed");
		if (_wi > 0) then {_spd = _wi};
		if (_wi < 0) then {_spd = _spd * (0 - _wi)};
		_spd = _spd max 100;
	};
	private _t0 = time;
	private _end = _t0 + _secs;
	private _next = 0;
	private _forceAt = _t0 + 8;
	private _lastMain = _t0;
	private _nMain = _n0;
	private _aimUp = false;	//--- nada disparo: el artillero mira al punto elevado por la caida del proyectil
	private _done = "";
	waitUntil {
		sleep 0.5;
		private _alive = _enemy && {alive _o};
		private _tgt = if (_alive) then {(getPosASL _o) vectorAdd [0, 0, 1]} else {_pA};
		private _d = (getPosASL _v) vectorDistance _tgt;
		private _aim = _tgt vectorAdd [0, 0, 0.5 * 9.81 * ((_d / _spd) ^ 2)];
		if ((_v getVariable ["vioc_fo_nMain", 0]) > _nMain) then {_nMain = _v getVariable ["vioc_fo_nMain", 0]; _lastMain = time};
		if (time >= _next) then {
			_next = time + 4;
			if (_alive) then {
				_g reveal [_o, 4];
				_g doWatch _o;
				_g doTarget _o;
				_g doFire _o;
				if (time > _t0 + 6 && {(_v getVariable ["vioc_fo_nAll", 0]) == _a0}) then {_v doSuppressiveFire _tgt};
			} else {
				if ((currentCommand _v) != "Suppress") then {
					_g doWatch (ASLToAGL (if (_aimUp) then {_aim} else {_tgt}));
					_v doSuppressiveFire _tgt;
					_v suppressFor ((_end - time) max 3);
				};
			};
			if (!isNull _cm && {alive _cm}) then {_cm doWatch (ASLToAGL _tgt); _cm doSuppressiveFire _tgt};
		};
		//--- respaldo: el canon no disparo solo -> se apunta con correccion de caida y se fuerza el disparo
		if (_w != "" && {_rt >= 1} && {time > _forceAt} && {(time - _lastMain) > (_rt + 3)} && {_d <= VIOC_FO_FORCE_MAX} && {_d > 15}) then {
			_forceAt = time + 1.5;
			if (!_alive && {(_v getVariable ["vioc_fo_nAll", 0]) == _a0}) then {_aimUp = true; _g doWatch (ASLToAGL _aim)};
			if ([_v, _w, _g, _aim] call VIOC_FO_fnc_aimed) then {
				_g forceWeaponFire [_mz, (weaponState [_v, _tp, _mz]) param [2, _mz]];
				_forceAt = time + (_rt max 2);
			};
		};
		if (_enemy && {!alive _o}) then {_done = "objetivo destruido"};
		if (!alive _v || {!alive _g} || {!canFire _v}) then {_done = "el vehiculo ya no puede disparar"};
		if ((_v getVariable ["vioc_fo_job", 0]) != _id) then {_done = "nueva"};
		if (_done == "" && {time >= _end}) then {_done = "tiempo"};
		_done != ""
	};
	if (_done == "nueva") exitWith {};
	if (alive _g) then {_g doWatch objNull};
	if (!isNull _cm && {alive _cm}) then {_cm doWatch objNull};
	[_v, _id] call VIOC_FO_fnc_restore;
	private _nM = (_v getVariable ["vioc_fo_nMain", 0]) - _n0;
	private _nA = (_v getVariable ["vioc_fo_nAll", 0]) - _a0;
	private _wn = if (_w != "") then {getText (configFile >> "CfgWeapons" >> _w >> "displayName")} else {""};
	private _txt = switch (_done) do {
		case "objetivo destruido": {format ["%1: objetivo destruido (%2 disparos).", _nm, _nA]};
		case "el vehiculo ya no puede disparar": {format ["%1 ya no puede disparar (danado, sin artillero o sin municion).", _nm]};
		default {format ["%1: fin del fuego (%2 disparos%3).", _nm, _nA, if (_wn != "") then {format [", %1 con %2", _nM, _wn]} else {""}]};
	};
	if (_nA == 0 && {_done == "tiempo"}) then {_txt = format ["%1 no disparo: sin linea de vista, fuera de alcance o sin municion para ese blanco. Prueba con otro punto o acercate.", _nm]};
	[_req, _txt, _v, true, 15] call VIOC_FO_fnc_tell;
};

//--- Artilleria (corre con spawn donde es local el artillero).
VIOC_FO_fnc_jobArty = {
	params ["_v", "", "_pA", "", "_mag", "_rounds", "", "_req"];
	private _nm = [_v] call VIOC_FO_fnc_vName;
	private _mode = call VIOC_FO_fnc_artyMode;
	if (_mode <= 0) exitWith {[_req, format ["%1: las ordenes de artilleria estan desactivadas en el lobby.", _nm], _v, true, 0] call VIOC_FO_fnc_tell};
	private _wait = 0;
	if (_mode == 2) then {_wait = ((_v getVariable ["vioc_fo_artyNext", -1]) - time) max 0};
	if (_wait > 0) exitWith {[_req, format ["%1: todavia no: espera entre misiones de fuego (faltan %2 s).", _nm, ceil _wait], _v, true, 0] call VIOC_FO_fnc_tell};
	private _pos = ASLToAGL _pA;
	_pos set [2, 0];
	if !(_mag in (getArtilleryAmmo [_v])) exitWith {[_req, format ["%1 ya no tiene esa municion.", _nm], _v, true, 0] call VIOC_FO_fnc_tell};
	if !(_pos inRangeOfArtillery [[_v], _mag]) exitWith {[_req, format ["%1: el punto esta fuera de su alcance (muy lejos o muy cerca).", _nm], _v, true, 0] call VIOC_FO_fnc_tell};
	private _id = [_v] call VIOC_FO_fnc_prep;
	[_v] call VIOC_FO_fnc_firedEH;
	_v setVariable ["vioc_fo_watchMag", _mag];
	_v setVariable ["vioc_fo_nMag", 0];
	if (_mode == 2) then {_v setVariable ["vioc_fo_artyNext", time + (missionNamespace getVariable ["CTI_ARTILLERY_TIMEOUT", 300])]};
	private _eta = _v getArtilleryETA [_pos, _mag];
	_v doArtilleryFire [_pos, _mag, _rounds];
	private _t0 = time;
	private _limit = _t0 + ((60 + _rounds * 15 + (_eta max 0)) min 480);
	private _seen = false;
	private _retry = false;
	private _first = false;
	private _why = "";
	waitUntil {
		sleep 1;
		private _n = _v getVariable ["vioc_fo_nMag", 0];
		if ((currentCommand _v) == "FIRE AT POSITION") then {_seen = true};
		if (_n > 0 && {!_first}) then {
			_first = true;
			[_req, format ["%1: disparando. Impacto en ~%2 s.", _nm, round ((_v getArtilleryETA [_pos, _mag]) max 0)], _v, false, 0] call VIOC_FO_fnc_tell;
		};
		if (!_seen && {_n == 0} && {!_retry} && {time > _t0 + 12}) then {_retry = true; _v commandArtilleryFire [_pos, _mag, _rounds]};
		if (_n >= _rounds) then {_why = "ok"};
		if (_why == "" && {_seen} && {time > _t0 + 5} && {(currentCommand _v) != "FIRE AT POSITION"}) then {_why = "fin"};
		if (_why == "" && {time > _limit}) then {_why = "tiempo"};
		if (_why == "" && {!alive _v || {!canFire _v} || {!alive (gunner _v)}}) then {_why = "perdido"};
		if ((_v getVariable ["vioc_fo_job", 0]) != _id) then {_why = "nueva"};
		_why != ""
	};
	if (_why == "nueva") exitWith {};
	[_v, _id] call VIOC_FO_fnc_restore;
	private _n = _v getVariable ["vioc_fo_nMag", 0];
	private _e = 0;
	if (alive _v) then {_e = (_v getArtilleryETA [_pos, _mag]) max 0};
	private _txt = if (_n == 0) then {
		format ["%1 no disparo (puede estar moviendose, sin esa municion o sin alcance). Detenlo y repite la orden.", _nm]
	} else {
		format ["%1: mision de fuego terminada: %2 de %3 disparos. Los ultimos caen en ~%4 s.", _nm, _n, _rounds, round _e]
	};
	[_req, _txt, _v, true, _e + 30] call VIOC_FO_fnc_tell;
};

//--- "Artillero: disparar a discrecion": tripulacion IA local del vehiculo en modo ROJO (o vuelta al modo anterior).
VIOC_FO_fnc_free = {
	params ["_v", "_on", "_req"];
	private _n = 0;
	{
		if (alive _x && {!isPlayer _x} && {local _x} && {(group _x) isEqualTo (group _req)}) then {
			if (_on) then {
				if (isNil {_x getVariable "vioc_fo_freePrev"}) then {_x setVariable ["vioc_fo_freePrev", unitCombatMode _x]};
				_x setUnitCombatMode "RED";
			} else {
				private _p = _x getVariable ["vioc_fo_freePrev", "YELLOW"];
				_x setVariable ["vioc_fo_freePrev", nil];
				if ((unitCombatMode _x) == "RED") then {_x setUnitCombatMode _p};
			};
			_n = _n + 1;
		};
	} forEach (crew _v);
	_v setVariable ["vioc_fo_free", _on, true];
	[_req, if (_on) then {format ["%1: disparar a discrecion ACTIVADO (%2 de la tripulacion en modo ROJO: disparan solos a todo enemigo que vean).", [_v] call VIOC_FO_fnc_vName, _n]} else {format ["%1: disparar a discrecion DESACTIVADO (la tripulacion vuelve a su modo de combate anterior).", [_v] call VIOC_FO_fnc_vName]}] call VIOC_FO_fnc_tell;
};

//--- Entrada de una orden (local, o por remoteExecCall al artillero desde el cliente que la dio).
//--- [vehiculo, "DIRECT"|"ARTY"|"FREE_ON"|"FREE_OFF", punto ASL, objeto enemigo, cargador, disparos, segundos, jugador]
VIOC_FO_fnc_exec = {
	params [["_v", objNull, [objNull]], ["_mode", "", [""]], ["_pA", [], [[]]], ["_o", objNull, [objNull]], ["_mag", "", [""]], ["_rounds", 1, [0]], ["_secs", 20, [0]], ["_req", objNull, [objNull]]];
	private _ro = remoteExecutedOwner;
	if (isMultiplayer && {_ro > 0} && {_ro != clientOwner} && {!isServer || {_ro != (owner _req)}}) exitWith {diag_log format ["[VIOC fire_orders] orden ignorada: la maquina %1 no controla al jugador", _ro]};
	if (isNull _v || {isNull _req} || {!isPlayer _req}) exitWith {};
	private _g = gunner _v;
	if (_mode in ["FREE_ON", "FREE_OFF"]) exitWith {[_v, _mode == "FREE_ON", _req] call VIOC_FO_fnc_free};
	if (!alive _v || {isNull _g} || {!alive _g} || {isPlayer _g} || {!((group _g) isEqualTo (group _req))}) exitWith {[_req, "Ese vehiculo ya no tiene artillero IA de tu grupo."] call VIOC_FO_fnc_tell};
	if (!local _g) exitWith {[_req, "El artillero cambio de maquina: repite la orden."] call VIOC_FO_fnc_tell};
	if (count _pA < 3) exitWith {};
	private _args = [_v, _mode, _pA, _o, _mag, (round _rounds) max 1, (_secs max 5) min 120, _req];
	if (_mode == "ARTY") exitWith {_args spawn VIOC_FO_fnc_jobArty};
	if (_mode == "DIRECT") exitWith {_args spawn VIOC_FO_fnc_jobDirect};
};

if (!hasInterface) exitWith {};

//=====================================================================================================================
//--- Cliente: acciones, mira, panel del mapa, marcas y avisos
//=====================================================================================================================
VIOC_FO_ROUNDS = [1, 3, 5, 10];
VIOC_FO_TIMES = [10, 20, 30, 45];
VIOC_FO_AV = false;
VIOC_FO_AV_T = -1;
VIOC_FO_AVM = false;
VIOC_FO_AVM_T = -1;
VIOC_FO_MKS = [];	//--- [[vehiculo, [marcadores], hasta (time)], ...]
VIOC_FO_MKN = 0;
VIOC_FO_POPEN = false;
VIOC_FO_P = [];		//--- entradas del panel: [vehiculo] o [varios de fuego directo]
VIOC_FO_PI = 0;
VIOC_FO_PMAGS = [];
VIOC_FO_PMI = 0;
VIOC_FO_PRI = 1;
VIOC_FO_PTI = (VIOC_FO_TIMES find VIOC_FO_SECS) max 0;
VIOC_FO_PPOS = [];
VIOC_FO_PCTRLS = [];
VIOC_FO_PINFO = controlNull;
VIOC_FO_PBMAG = controlNull;
VIOC_FO_PBNUM = controlNull;
VIOC_FO_PKEY = "";
VIOC_FO_MK = "vioc_fo_click";
VIOC_FO_MKZ = "vioc_fo_click_z";

//--- Texto seguro para parseText.
VIOC_FO_fnc_esc = {
	params [["_s", "", [""]]];
	private _o = [];
	{
		switch (_x) do {
			case 38: {_o append (toArray "&amp;")};
			case 60: {_o append (toArray "&lt;")};
			case 62: {_o append (toArray "&gt;")};
			default {_o pushBack _x};
		};
	} forEach (toArray _s);
	toString _o
};

//--- Vehiculo con artillero IA vivo de TU grupo que puede disparar.
VIOC_FO_fnc_ok = {
	params ["_v"];
	if (isNull _v || {_v isKindOf "CAManBase"} || {!alive _v}) exitWith {false};
	private _g = gunner _v;
	!isNull _g && {alive _g} && {!isPlayer _g} && {(group _g) isEqualTo (group player)} && {canFire _v}
};

//--- Vehiculos de tu grupo con artillero IA (si eres el lider del grupo).
VIOC_FO_fnc_vehicles = {
	private _out = [];
	if !((leader (group player)) isEqualTo player) exitWith {_out};
	{
		private _v = vehicle _x;
		if (!(_v isEqualTo _x) && {!(_v in _out)} && {[_v] call VIOC_FO_fnc_ok}) then {_out pushBack _v};
	} forEach (units (group player));
	_out
};

//--- El vehiculo en el que vas, si tiene artillero IA de tu grupo (tu de jefe, conductor o pasajero).
VIOC_FO_fnc_myVeh = {
	private _v = vehicle player;
	if ((_v isEqualTo player) || {(gunner _v) isEqualTo player} || {!((leader (group player)) isEqualTo player)}) exitWith {objNull};
	if ([_v] call VIOC_FO_fnc_ok) then {_v} else {objNull}
};

//--- Condiciones de las acciones (se miran cada cuadro: se recalculan 1 vez por segundo).
VIOC_FO_fnc_avail = {
	if (diag_tickTime < VIOC_FO_AV_T) exitWith {VIOC_FO_AV};
	VIOC_FO_AV_T = diag_tickTime + 1;
	VIOC_FO_AV = (count (call VIOC_FO_fnc_vehicles)) > 0;
	VIOC_FO_AV
};
VIOC_FO_fnc_availMine = {
	if (diag_tickTime < VIOC_FO_AVM_T) exitWith {VIOC_FO_AVM};
	VIOC_FO_AVM_T = diag_tickTime + 1;
	VIOC_FO_AVM = !isNull (call VIOC_FO_fnc_myVeh);
	VIOC_FO_AVM
};

//--- [vehiculo] -> [[cargador, nombre, disparos que le quedan], ...] de artilleria, HE primero (sin cargas nucleares).
VIOC_FO_fnc_artyRank = {
	params ["_m"];
	private _s = toLower (_m + " " + (getText (configFile >> "CfgMagazines" >> _m >> "displayName")) + " " + (getText (configFile >> "CfgMagazines" >> _m >> "ammo")));
	private _has = {(_this findIf {(_s find _x) >= 0}) >= 0};
	if (["mine", "adam", "raams", "fascam", "m731"] call _has) exitWith {5};
	if (["illum", "flare", "_ilum", "m485"] call _has) exitWith {4};
	if (["smoke", "_wp", " wp", "phosph", "m825"] call _has) exitWith {3};
	if (["_lg", "laser", "guided", "copperhead", "m712", "krasnopol", "excalibur"] call _has) exitWith {2};
	if (["cluster", "dpicm", "icm", "m864", "m26"] call _has) exitWith {1};
	if ((getNumber (configFile >> "CfgAmmo" >> (getText (configFile >> "CfgMagazines" >> _m >> "ammo")) >> "artilleryLock")) <= 0) exitWith {6};
	0
};
VIOC_FO_fnc_artyMags = {
	params ["_v"];
	private _all = magazinesAllTurrets _v;
	private _out = [];
	{
		private _m = _x;
		private _nm = getText (configFile >> "CfgMagazines" >> _m >> "displayName");
		if (_nm == "") then {_nm = _m};
		private _s = toLower (_m + " " + _nm);
		if (((["atomic", "nuclear", "nuke"] findIf {(_s find _x) >= 0}) < 0)) then {
			private _n = 0;
			{if ((_x select 0) == _m) then {_n = _n + (_x select 2)}} forEach _all;
			if (_n > 0) then {_out pushBack [[_m] call VIOC_FO_fnc_artyRank, _nm, _m, _n]};
		};
	} forEach (getArtilleryAmmo [_v]);
	_out sort true;
	_out apply {[_x select 2, _x select 1, _x select 3]}
};

//--- Tropas propias (no civiles) cerca de un punto: [posicion AGL, radio, vehiculos que disparan] -> [cuantas, nombres]
VIOC_FO_fnc_friendsNear = {
	params ["_p", "_r", "_shooters"];
	private _side = side group player;
	private _n = 0;
	private _names = [];
	{
		private _o = _x;
		if !(_o in _shooters) then {
			private _crew = if (_o isKindOf "CAManBase") then {[_o]} else {crew _o};
			{
				private _sx = side group _x;
				if (alive _x && {_sx != civilian} && {(_sx isEqualTo _side) || {(_side getFriend _sx) >= 0.6}} && {!((vehicle _x) in _shooters)}) then {
					_n = _n + 1;
					if (count _names < 3) then {_names pushBackUnique (if (isPlayer _x) then {name _x} else {getText (configOf (vehicle _x) >> "displayName")})};
				};
			} forEach _crew;
		};
	} forEach (_p nearEntities [["CAManBase", "LandVehicle", "Air", "Ship"], _r]);
	[_n, _names joinString ", "]
};

//--- Lo que hay bajo la mira (centro de la pantalla): [posicion ASL, objeto o objNull]
VIOC_FO_fnc_look = {
	private _from = AGLToASL (positionCameraToWorld [0, 0, 0]);
	private _to = AGLToASL (positionCameraToWorld [0, 0, (viewDistance max 1000) min 6000]);
	private _hits = lineIntersectsSurfaces [_from, _to, vehicle player, player, true, 1, "VIEW", "FIRE"];
	if (count _hits > 0) exitWith {
		private _h = _hits select 0;
		private _o = _h select 3;
		if (isNull _o) then {_o = _h select 2};
		[_h select 0, _o]
	};
	private _p = screenToWorld [0.5, 0.5];
	if ((_p distance2D (positionCameraToWorld [0, 0, 0])) < 5) exitWith {[[], objNull]};
	[AGLToASL _p, objNull]
};

//--- Marca la orden en TU mapa (punto + circulo de seguridad); se borra al terminar (o a los _life s).
VIOC_FO_fnc_unmark = {
	params ["_v"];
	private _i = VIOC_FO_MKS findIf {(_x select 0) isEqualTo _v};
	if (_i >= 0) then {
		{deleteMarkerLocal _x} forEach ((VIOC_FO_MKS select _i) select 1);
		VIOC_FO_MKS deleteAt _i;
	};
};
VIOC_FO_fnc_mark = {
	params ["_v", "_pG", "_text", "_r", "_life"];
	[_v] call VIOC_FO_fnc_unmark;
	VIOC_FO_MKN = VIOC_FO_MKN + 1;
	private _a = createMarkerLocal [format ["vioc_fo_t%1", VIOC_FO_MKN], _pG];
	_a setMarkerTypeLocal "mil_destroy";
	_a setMarkerColorLocal "ColorRed";
	_a setMarkerTextLocal _text;
	private _b = createMarkerLocal [format ["vioc_fo_z%1", VIOC_FO_MKN], _pG];
	_b setMarkerShapeLocal "ELLIPSE";
	_b setMarkerSizeLocal [_r, _r];
	_b setMarkerBrushLocal "Border";
	_b setMarkerColorLocal "ColorRed";
	VIOC_FO_MKS pushBack [_v, [_a, _b], time + _life];
};

//--- Aviso para ti (de VIOC_FO_fnc_tell). Al terminar una orden, su marca se borra a los _keep s.
VIOC_FO_fnc_note = {
	params [["_text", "", [""]], ["_v", objNull], ["_end", false], ["_keep", 0]];
	systemChat format ["[Fuego] %1", _text];
	hint parseText format ["<t size='1.05' color='#ffb35c'>Orden de fuego</t><br/><br/><t align='left'>%1</t>", [_text] call VIOC_FO_fnc_esc];
	if (_end isEqualTo true && {!isNull _v}) then {
		private _i = VIOC_FO_MKS findIf {(_x select 0) isEqualTo _v};
		if (_i >= 0) then {(VIOC_FO_MKS select _i) set [2, time + (_keep max 5)]};
	};
};

//--- Manda una orden: [vehiculo, "DIRECT"|"ARTY", punto ASL, objeto, cargador, disparos, segundos, tiradores] -> [ok, texto]
VIOC_FO_fnc_send = {
	params ["_v", "_mode", "_pA", ["_o", objNull], ["_mag", ""], ["_rounds", 1], ["_secs", 20], ["_shooters", []]];
	private _nm = [_v] call VIOC_FO_fnc_vName;
	if !([_v] call VIOC_FO_fnc_ok) exitWith {[false, format ["%1: ya no tiene artillero IA de tu grupo (o no puede disparar).", _nm]]};
	if (count _shooters == 0) then {_shooters = [_v]};
	private _pG = ASLToAGL _pA;
	private _isA = _mode == "ARTY";
	private _side = side group player;
	private _err = "";
	if (_isA) then {
		_err = call {
			if ((call VIOC_FO_fnc_artyMode) <= 0) exitWith {"las ordenes de artilleria estan desactivadas en el lobby"};
			if !(_mag in (getArtilleryAmmo [_v])) exitWith {"no tiene esa municion"};
			private _cap = missionNamespace getVariable ["CTI_ARTILLERY_SETUP", 15000];
			if (_cap isEqualType 0 && {_cap > 0} && {(_v distance2D _pG) > _cap}) exitWith {format ["el punto esta a %1 m y la mision limita la artilleria a %2 m (lobby ARTILLERY: Setup)", round (_v distance2D _pG), _cap]};
			if !([_pG select 0, _pG select 1, 0] inRangeOfArtillery [[_v], _mag]) exitWith {"el punto esta fuera de su alcance (muy lejos o muy cerca)"};
			""
		};
	};
	if (_err != "") exitWith {[false, format ["%1: %2.", _nm, _err]]};
	//--- no se dispara a lo propio
	if (!isNull _o && {alive _o} && {!([_o, _side] call VIOC_FO_fnc_isEnemy)}) then {
		private _oc = if (_o isKindOf "CAManBase") then {[_o]} else {(crew _o) select {alive _x}};
		if (count _oc > 0 && {(side group (_oc select 0)) != civilian}) then {_err = "eso es de tu bando: no disparo"};
	};
	if (_err != "") exitWith {[false, format ["%1: %2.", _nm, _err]]};
	private _r = if (_isA) then {VIOC_FO_SAFE_ARTY} else {VIOC_FO_SAFE_DIRECT};
	private _f = [_pG, _r, _shooters] call VIOC_FO_fnc_friendsNear;
	if ((_f select 0) > 0) exitWith {[false, format ["%1 NO dispara: hay %2 de los tuyos a menos de %3 m del punto (%4).", _nm, _f select 0, _r, _f select 1]]};
	private _enemy = [_o, _side] call VIOC_FO_fnc_isEnemy;
	private _txt = "";
	if (_isA) then {
		private _eta = _v getArtilleryETA [[_pG select 0, _pG select 1, 0], _mag];
		private _mn = getText (configFile >> "CfgMagazines" >> _mag >> "displayName");
		[_v, _pG, format ["Artilleria: %1 x%2", _nm, _rounds], _r, 180 + _rounds * 20 + (_eta max 0)] call VIOC_FO_fnc_mark;
		_txt = format ["%1: %2 disparos de %3 sobre la cuadricula %4. Llegada ~%5 s despues de cada disparo.", _nm, _rounds, _mn, mapGridPosition _pG, round (_eta max 0)];
	} else {
		private _tp = (assignedVehicleRole (gunner _v)) param [1, [0]];
		if !(_tp isEqualType []) then {_tp = [0]};
		private _pk = [_v, _tp, if (_enemy) then {[_o] call VIOC_FO_fnc_kindOf} else {"HE"}] call VIOC_FO_fnc_pickWeapon;
		private _mn = if ((_pk select 2) != "") then {getText (configFile >> "CfgMagazines" >> (_pk select 2) >> "displayName")} else {"la que tenga"};
		[_v, _pG, format ["Fuego: %1", _nm], _r, _secs + 120] call VIOC_FO_fnc_mark;
		_txt = if (_enemy) then {
			format ["%1: ataca a %2 (%3 m) con %4.", _nm, getText (configOf _o >> "displayName"), round (_v distance _o), _mn]
		} else {
			format ["%1: fuego sobre la cuadricula %2 (%3 m) durante %4 s con %5.", _nm, mapGridPosition _pG, round (_v distance2D _pG), _secs, _mn]
		};
	};
	private _args = [_v, _mode, _pA, if (_enemy) then {_o} else {objNull}, _mag, _rounds, _secs, player];
	private _g = gunner _v;
	if (local _g) then {_args call VIOC_FO_fnc_exec} else {_args remoteExecCall ["VIOC_FO_fnc_exec", _g]};
	[true, _txt]
};

//--- Muestra el resultado de una o varias ordenes.
VIOC_FO_fnc_showRes = {
	params ["_res"];
	private _ok = {_x select 0} count _res;
	{systemChat format ["[Fuego] %1", _x select 1]} forEach _res;
	hint parseText format ["<t size='1.05' color='%1'>%2</t><br/><br/><t align='left'>%3</t>", if (_ok > 0) then {"#ffb35c"} else {"#F56363"}, if (_ok > 0) then {"Orden de fuego"} else {"Orden de fuego: no"}, (_res apply {[_x select 1] call VIOC_FO_fnc_esc}) joinString "<br/><br/>"];
	_ok
};

//--- Accion "ORDEN: Atacar donde miro".
VIOC_FO_fnc_quick = {
	if (!alive player) exitWith {};
	(call VIOC_FO_fnc_look) params ["_pA", "_o"];
	if (count _pA < 3) exitWith {hint "Apunta a un punto del suelo, a una casa o a un objetivo y vuelve a dar la orden."};
	if (!isNull _o && {!(_o isKindOf "AllVehicles") || {!alive _o}}) then {_o = objNull};
	private _mine = call VIOC_FO_fnc_myVeh;
	private _vs = [];
	if (!isNull _mine) then {
		_vs = [_mine];
	} else {
		private _all = call VIOC_FO_fnc_vehicles;
		private _sel = (groupSelectedUnits player) apply {vehicle _x};
		_vs = _all select {_x in _sel};
		if (count _vs == 0) then {_vs = _all select {!([_x] call VIOC_FO_fnc_isArty)}};
	};
	if (count _vs == 0) exitWith {hint "No hay vehiculos con artillero IA en tu grupo para esta orden (la artilleria solo dispara si la seleccionas con F2, F3... o desde ORDEN: Atacar punto (mapa))."};
	private _res = [];
	{
		private _v = _x;
		if ([_v] call VIOC_FO_fnc_isArty) then {
			private _ms = [_v] call VIOC_FO_fnc_artyMags;
			if (count _ms == 0) then {
				_res pushBack [false, format ["%1 no tiene municion de artilleria.", [_v] call VIOC_FO_fnc_vName]];
			} else {
				private _m = _ms select 0;
				_res pushBack ([_v, "ARTY", _pA, objNull, _m select 0, 3 min (_m select 2), 0, _vs] call VIOC_FO_fnc_send);
			};
		} else {
			_res pushBack ([_v, "DIRECT", _pA, _o, "", 0, VIOC_FO_SECS, _vs] call VIOC_FO_fnc_send);
		};
	} forEach _vs;
	[_res] call VIOC_FO_fnc_showRes;
};

//--- Accion "Artillero: disparar a discrecion (ON/OFF)".
VIOC_FO_fnc_toggleFree = {
	private _v = call VIOC_FO_fnc_myVeh;
	if (isNull _v) exitWith {hint "Tienes que ir en un vehiculo con artillero IA de tu grupo."};
	private _on = !(_v getVariable ["vioc_fo_free", false]);
	private _args = [_v, if (_on) then {"FREE_ON"} else {"FREE_OFF"}, [], objNull, "", 0, 0, player];
	private _g = gunner _v;
	if (local _g) then {_args call VIOC_FO_fnc_exec} else {_args remoteExecCall ["VIOC_FO_fnc_exec", _g]};
};

//--- Estado para la consola.
VIOC_FO_fnc_status = {
	private _l = [];
	{
		private _g = gunner _x;
		_l pushBack format ["%1: %2; artillero %3 (modo %4, LAMBS apagado %5); orden actual '%6'; libre %7", [_x] call VIOC_FO_fnc_vName, if ([_x] call VIOC_FO_fnc_isArty) then {"artilleria"} else {"fuego directo"}, name _g, unitCombatMode _g, _g getVariable ["lambs_danger_disableAI", false], currentCommand _x, _x getVariable ["vioc_fo_free", false]];
	} forEach (call VIOC_FO_fnc_vehicles);
	if (count _l == 0) then {_l pushBack "Sin vehiculos con artillero IA en tu grupo."};
	format ["Grupo: modo %1, comportamiento %2\n%3", combatMode (group player), behaviour player, _l joinString "\n"]
};

//--- Borra las marcas vencidas (cada 10 s).
[] spawn {
	while {true} do {
		sleep 10;
		private _old = VIOC_FO_MKS select {(time > (_x select 2)) || {isNull (_x select 0)}};
		{[_x select 0] call VIOC_FO_fnc_unmark} forEach _old;
	};
};

//=====================================================================================================================
//--- Panel del mapa ("ORDEN: Atacar punto (mapa)")
//=====================================================================================================================
VIOC_FO_fnc_cmName = {
	params ["_m"];
	switch (_m) do {
		case "BLUE": {"nunca disparar"};
		case "GREEN": {"mantener fuego"};
		case "WHITE": {"mantener fuego (enfrentar a voluntad)"};
		case "YELLOW": {"fuego a discrecion"};
		case "RED": {"fuego a discrecion (enfrentar a voluntad)"};
		default {_m};
	}
};

//--- Entradas: tu vehiculo primero, luego los demas de tu grupo y, si hay 2 o mas de fuego directo, "todos".
VIOC_FO_fnc_pBuildList = {
	private _vs = call VIOC_FO_fnc_vehicles;
	private _mine = call VIOC_FO_fnc_myVeh;
	private _l = [];
	if (!isNull _mine) then {_l pushBack [_mine]};
	{if !(_x isEqualTo _mine) then {_l pushBack [_x]}} forEach _vs;
	private _d = _vs select {!([_x] call VIOC_FO_fnc_isArty)};
	if (count _d > 1) then {_l pushBack _d};
	VIOC_FO_P = _l;
	if (VIOC_FO_PI >= count _l) then {VIOC_FO_PI = 0};
	VIOC_FO_PKEY = "";
};

//--- Vehiculos de la entrada elegida que siguen sirviendo.
VIOC_FO_fnc_pEntry = {
	private _e = (VIOC_FO_P param [VIOC_FO_PI, []]) select {[_x] call VIOC_FO_fnc_ok};
	if (count _e == 0 && {count VIOC_FO_P > 0}) then {
		call VIOC_FO_fnc_pBuildList;
		_e = (VIOC_FO_P param [VIOC_FO_PI, []]) select {[_x] call VIOC_FO_fnc_ok};
	};
	_e
};

//--- La entrada es una sola pieza de artilleria.
VIOC_FO_fnc_pIsArty = {
	params ["_e"];
	(count _e == 1) && {[_e select 0] call VIOC_FO_fnc_isArty}
};

VIOC_FO_fnc_pRefresh = {
	if (isNull VIOC_FO_PINFO) exitWith {};
	private _e = call VIOC_FO_fnc_pEntry;
	private _l = [];
	if (count _e == 0) exitWith {
		VIOC_FO_PINFO ctrlSetStructuredText parseText "<t size='0.85' color='#F56363'>No tienes vehiculos con artillero IA en tu grupo (o no eres el lider del grupo).</t>";
	};
	private _isA = [_e] call VIOC_FO_fnc_pIsArty;
	private _v = _e select 0;
	private _key = str _e;
	if (_isA) then {
		//--- municion al dia (quedan N); se conserva la elegida si sigue el mismo vehiculo
		private _cur = if (_key == VIOC_FO_PKEY) then {(VIOC_FO_PMAGS param [VIOC_FO_PMI, []]) param [0, ""]} else {""};
		VIOC_FO_PMAGS = [_v] call VIOC_FO_fnc_artyMags;
		VIOC_FO_PMI = (VIOC_FO_PMAGS findIf {(_x select 0) == _cur}) max 0;
	};
	VIOC_FO_PKEY = _key;
	private _r = if (_isA) then {VIOC_FO_SAFE_ARTY} else {VIOC_FO_SAFE_DIRECT};
	if (count _e == 1) then {
		_l pushBack format ["<t color='#ffcf99'>Vehiculo (%1/%2):</t> %3 - %4 - a %5 m de ti", VIOC_FO_PI + 1, count VIOC_FO_P, [[_v] call VIOC_FO_fnc_vName] call VIOC_FO_fnc_esc, if (_isA) then {"artilleria"} else {"fuego directo"}, round (player distance _v)];
	} else {
		_l pushBack format ["<t color='#ffcf99'>Vehiculo (%1/%2):</t> TODOS los de fuego directo (%3): %4", VIOC_FO_PI + 1, count VIOC_FO_P, count _e, [(_e apply {[_x] call VIOC_FO_fnc_vName}) joinString ", "] call VIOC_FO_fnc_esc];
	};
	private _cmd = combatMode (group player);
	if (_cmd in ["BLUE", "GREEN", "WHITE"]) then {_l pushBack format ["<t color='#F5D363'>Tu grupo esta en '%1': la orden lo sube a fuego a discrecion solo mientras dura.</t>", [_cmd] call VIOC_FO_fnc_cmName]};
	private _hasP = count VIOC_FO_PPOS >= 2;
	private _pG = if (_hasP) then {[VIOC_FO_PPOS select 0, VIOC_FO_PPOS select 1, 0]} else {[]};
	_l pushBack format ["<t color='#ffcf99'>Punto:</t> %1", if (_hasP) then {format ["cuadricula %1, a %2 m del vehiculo", mapGridPosition _pG, round (_v distance2D _pG)]} else {"<t color='#F5D363'>haz clic en el mapa</t>"}];
	if (_isA) then {
		private _m = VIOC_FO_PMAGS param [VIOC_FO_PMI, []];
		private _nr = VIOC_FO_ROUNDS select VIOC_FO_PRI;
		if (count _m == 0) then {
			_l pushBack "<t color='#F56363'>No le queda municion de artilleria.</t>";
		} else {
			_l pushBack format ["<t color='#ffcf99'>Municion (%1/%2):</t> %3 (quedan %4)", VIOC_FO_PMI + 1, count VIOC_FO_PMAGS, [_m select 1] call VIOC_FO_fnc_esc, _m select 2];
			_l pushBack format ["<t color='#ffcf99'>Disparos:</t> %1%2", _nr, if (_nr > (_m select 2)) then {format [" (solo quedan %1)", _m select 2]} else {""}];
			if (_hasP) then {
				private _in = _pG inRangeOfArtillery [[_v], _m select 0];
				private _eta = _v getArtilleryETA [_pG, _m select 0];
				_l pushBack format ["<t color='#ffcf99'>Alcance:</t> %1", if (_in) then {format ["<t color='#76F563'>SI</t> - llegada ~%1 s despues de cada disparo", round (_eta max 0)]} else {"<t color='#F56363'>NO (muy lejos o muy cerca)</t>"}];
			};
		};
		if ((call VIOC_FO_fnc_artyMode) <= 0) then {_l pushBack "<t color='#F56363'>Las ordenes de artilleria estan desactivadas en el lobby.</t>"};
	} else {
		private _tp = (assignedVehicleRole (gunner _v)) param [1, [0]];
		if !(_tp isEqualType []) then {_tp = [0]};
		private _pk = [_v, _tp, "HE"] call VIOC_FO_fnc_pickWeapon;
		if ((_pk select 2) != "") then {
			private _left = {_x == (_pk select 2)} count (_v magazinesTurret _tp);
			_l pushBack format ["<t color='#ffcf99'>Municion:</t> %1 con %2 (cargadores: %3)", [getText (configFile >> "CfgMagazines" >> (_pk select 2) >> "displayName")] call VIOC_FO_fnc_esc, [getText (configFile >> "CfgWeapons" >> (_pk select 0) >> "displayName")] call VIOC_FO_fnc_esc, _left];
		};
		_l pushBack format ["<t color='#ffcf99'>Fuego:</t> %1 s sobre el punto (el artillero apunta y dispara solo)", VIOC_FO_TIMES select VIOC_FO_PTI];
		if (_hasP && {(_v distance2D _pG) > 2500}) then {_l pushBack "<t color='#F5D363'>A mas de 2500 m: puede que no alcance o no lo vea.</t>"};
	};
	if (_hasP) then {
		private _f = [_pG, _r, _e] call VIOC_FO_fnc_friendsNear;
		_l pushBack (if ((_f select 0) > 0) then {format ["<t color='#F56363'>Hay %1 de los tuyos a menos de %2 m: NO disparara (%3).</t>", _f select 0, _r, [_f select 1] call VIOC_FO_fnc_esc]} else {format ["<t color='#76F563'>Sin tropas propias a menos de %1 m.</t>", _r]});
	};
	VIOC_FO_PINFO ctrlSetStructuredText parseText format ["<t size='0.82'>%1</t>", _l joinString "<br/>"];
	if (!isNull VIOC_FO_PBMAG) then {VIOC_FO_PBMAG ctrlEnable _isA; VIOC_FO_PBMAG ctrlSetText (if (_isA) then {"CAMBIAR MUNICION"} else {"MUNICION: AUTO"})};
	if (!isNull VIOC_FO_PBNUM) then {VIOC_FO_PBNUM ctrlSetText (if (_isA) then {format ["DISPAROS: %1", VIOC_FO_ROUNDS select VIOC_FO_PRI]} else {format ["TIEMPO: %1 s", VIOC_FO_TIMES select VIOC_FO_PTI]})};
	//--- circulo de seguridad del clic con el radio de esta entrada
	if (_hasP) then {VIOC_FO_MKZ setMarkerSizeLocal [_r, _r]};
};

VIOC_FO_fnc_pNextVeh = {
	if (count VIOC_FO_P == 0) then {call VIOC_FO_fnc_pBuildList};
	if (count VIOC_FO_P > 0) then {VIOC_FO_PI = (VIOC_FO_PI + 1) mod (count VIOC_FO_P)};
	VIOC_FO_PKEY = "";
	call VIOC_FO_fnc_pRefresh;
};
VIOC_FO_fnc_pNextMag = {
	if (count VIOC_FO_PMAGS > 0) then {VIOC_FO_PMI = (VIOC_FO_PMI + 1) mod (count VIOC_FO_PMAGS)};
	call VIOC_FO_fnc_pRefresh;
};
VIOC_FO_fnc_pNextNum = {
	if ([call VIOC_FO_fnc_pEntry] call VIOC_FO_fnc_pIsArty) then {
		VIOC_FO_PRI = (VIOC_FO_PRI + 1) mod (count VIOC_FO_ROUNDS);
	} else {
		VIOC_FO_PTI = (VIOC_FO_PTI + 1) mod (count VIOC_FO_TIMES);
	};
	call VIOC_FO_fnc_pRefresh;
};

//--- Clic en el mapa: punto + circulo de seguridad.
VIOC_FO_fnc_pClick = {
	params ["_pos"];
	VIOC_FO_PPOS = [_pos select 0, _pos select 1, 0];
	deleteMarkerLocal VIOC_FO_MK;
	deleteMarkerLocal VIOC_FO_MKZ;
	private _z = createMarkerLocal [VIOC_FO_MKZ, VIOC_FO_PPOS];
	_z setMarkerShapeLocal "ELLIPSE";
	_z setMarkerSizeLocal [VIOC_FO_SAFE_DIRECT, VIOC_FO_SAFE_DIRECT];
	_z setMarkerBrushLocal "Border";
	_z setMarkerColorLocal "ColorOrange";
	private _m = createMarkerLocal [VIOC_FO_MK, VIOC_FO_PPOS];
	_m setMarkerTypeLocal "mil_destroy";
	_m setMarkerColorLocal "ColorOrange";
	_m setMarkerTextLocal "Punto a atacar";
	call VIOC_FO_fnc_pRefresh;
};

//--- FUEGO
VIOC_FO_fnc_pFire = {
	private _e = call VIOC_FO_fnc_pEntry;
	if (count _e == 0) exitWith {hint "No tienes vehiculos con artillero IA en tu grupo."};
	if (count VIOC_FO_PPOS < 2) exitWith {hint "Haz clic en el mapa para elegir el punto a atacar."};
	private _pA = AGLToASL [VIOC_FO_PPOS select 0, VIOC_FO_PPOS select 1, 0];
	private _res = [];
	if ([_e] call VIOC_FO_fnc_pIsArty) then {
		private _m = VIOC_FO_PMAGS param [VIOC_FO_PMI, []];
		if (count _m == 0) then {
			_res pushBack [false, "No le queda municion de artilleria."];
		} else {
			_res pushBack ([_e select 0, "ARTY", _pA, objNull, _m select 0, (VIOC_FO_ROUNDS select VIOC_FO_PRI) min (_m select 2), 0, _e] call VIOC_FO_fnc_send);
		};
	} else {
		{_res pushBack ([_x, "DIRECT", _pA, objNull, "", 0, VIOC_FO_TIMES select VIOC_FO_PTI, _e] call VIOC_FO_fnc_send)} forEach _e;
	};
	if (([_res] call VIOC_FO_fnc_showRes) > 0) then {
		VIOC_FO_POPEN = false;
		openMap false;
	};
};

//--- Crea el panel sobre el mapa (pantalla 12). Devuelve true si pudo.
VIOC_FO_fnc_pBuild = {
	params ["_d"];
	VIOC_FO_PCTRLS = [];
	private _mk = {
		params ["_cls", "_pos"];
		private _c = _d ctrlCreate [_cls, -1];
		_c ctrlSetPosition _pos;
		_c ctrlCommit 0;
		VIOC_FO_PCTRLS pushBack _c;
		_c
	};
	private _W = safeZoneW;
	private _H = safeZoneH;
	private _x0 = safeZoneX + _W * 0.715;
	private _y0 = safeZoneY + _H * 0.08;
	private _w = _W * 0.275;
	private _p = _W * 0.006;
	private _lh = _H * 0.034;
	private _iw = _w - 2 * _p;
	private _bw = (_iw - _p) / 2;
	private _bh = _lh * 1.15;
	private _bg = ["RscText", [_x0, _y0, _w, _H * 0.66]] call _mk;
	if (isNull _bg) exitWith {false};
	_bg ctrlSetBackgroundColor [0, 0, 0, 0.8];
	private _y = _y0 + _p;
	private _t = ["RscStructuredText", [_x0 + _p, _y, _iw, _lh * 3.2]] call _mk;
	_t ctrlSetStructuredText parseText "<t size='1.05' color='#ffb35c'>ORDEN DE FUEGO</t><br/><t size='0.8'>Clic en el mapa: el punto a atacar. Tu IA dispara sola (sin decirle 'fuego'). No dispara si hay tropas propias cerca del punto.</t>";
	_y = _y + _lh * 3.3;
	private _info = ["RscStructuredText", [_x0 + _p, _y, _iw, _H * 0.36]] call _mk;
	_y = _y + _H * 0.36 + _p;
	private _bv = ["RscButton", [_x0 + _p, _y, _iw, _bh]] call _mk;
	_bv ctrlSetText "CAMBIAR VEHICULO";
	_bv ctrlAddEventHandler ["ButtonClick", "with missionNamespace do {call VIOC_FO_fnc_pNextVeh}"];
	_y = _y + _bh + _p;
	private _bm = ["RscButton", [_x0 + _p, _y, _bw, _bh]] call _mk;
	_bm ctrlSetText "CAMBIAR MUNICION";
	_bm ctrlAddEventHandler ["ButtonClick", "with missionNamespace do {call VIOC_FO_fnc_pNextMag}"];
	private _bn = ["RscButton", [_x0 + _p * 2 + _bw, _y, _bw, _bh]] call _mk;
	_bn ctrlSetText "DISPAROS";
	_bn ctrlAddEventHandler ["ButtonClick", "with missionNamespace do {call VIOC_FO_fnc_pNextNum}"];
	_y = _y + _bh + _p;
	private _ok = ["RscButton", [_x0 + _p, _y, _bw, _bh]] call _mk;
	_ok ctrlSetText "FUEGO";
	_ok ctrlSetBackgroundColor [0.75, 0.35, 0.1, 1];
	_ok ctrlAddEventHandler ["ButtonClick", "with missionNamespace do {call VIOC_FO_fnc_pFire}"];
	private _ko = ["RscButton", [_x0 + _p * 2 + _bw, _y, _bw, _bh]] call _mk;
	_ko ctrlSetText "CANCELAR";
	_ko ctrlAddEventHandler ["ButtonClick", "with missionNamespace do {VIOC_FO_POPEN = false; openMap false}"];
	VIOC_FO_PINFO = _info;
	VIOC_FO_PBMAG = _bm;
	VIOC_FO_PBNUM = _bn;
	true
};

//--- Cierra el panel: controles, marcas del clic y evento del mapa.
VIOC_FO_fnc_pClose = {
	if (!isNil "VIOC_FO_EH") then {removeMissionEventHandler ["MapSingleClick", VIOC_FO_EH]; VIOC_FO_EH = nil};
	{if (!isNull _x) then {ctrlDelete _x}} forEach VIOC_FO_PCTRLS;
	VIOC_FO_PCTRLS = [];
	VIOC_FO_PINFO = controlNull;
	VIOC_FO_PBMAG = controlNull;
	VIOC_FO_PBNUM = controlNull;
	deleteMarkerLocal VIOC_FO_MK;
	deleteMarkerLocal VIOC_FO_MKZ;
	VIOC_FO_POPEN = false;
};

//--- Accion "ORDEN: Atacar punto (mapa)" (se corre con spawn).
VIOC_FO_fnc_open = {
	if (VIOC_FO_POPEN) exitWith {};
	if (!alive player) exitWith {};
	call VIOC_FO_fnc_pBuildList;
	if (count VIOC_FO_P == 0) exitWith {hint "No tienes vehiculos con artillero IA en tu grupo (o no eres el lider del grupo)."};
	VIOC_FO_POPEN = true;
	VIOC_FO_PPOS = [];
	VIOC_FO_PI = 0;
	openMap [true, false];
	private _t = diag_tickTime + 3;
	waitUntil {sleep 0.05; visibleMap || {diag_tickTime > _t}};
	private _d = findDisplay 12;
	if (!visibleMap || {isNull _d} || {!([_d] call VIOC_FO_fnc_pBuild)}) exitWith {
		call VIOC_FO_fnc_pClose;
		hint "No se pudo abrir el panel del mapa. Prueba otra vez con el mapa cerrado.";
	};
	VIOC_FO_EH = addMissionEventHandler ["MapSingleClick", {
		params ["", "_pos"];
		[_pos] call VIOC_FO_fnc_pClick;
	}];
	call VIOC_FO_fnc_pRefresh;
	private _next = diag_tickTime + 1;
	waitUntil {
		sleep 0.1;
		if (diag_tickTime > _next) then {_next = diag_tickTime + 1; call VIOC_FO_fnc_pRefresh};
		!visibleMap || {!alive player} || {!VIOC_FO_POPEN}
	};
	call VIOC_FO_fnc_pClose;
	if (visibleMap) then {openMap false};
};

class VIOC_FIRE_ORDERS {
	title = "VIOC: Ordenes de fuego a tu IA (acciones ORDEN: Atacar donde miro / Atacar punto (mapa): el artillero IA de tus vehiculos dispara solo al punto u objetivo; artilleria con municion, disparos y tiempo de llegada)";
	values[] = {0,1};
	texts[] = {"No","Si"};
	default = 1;
};
class VIOC_FIRE_ORDERS_TIME {
	title = "VIOC: Ordenes de fuego: segundos de fuego directo sobre un punto (supresion)";
	values[] = {10,20,30,45};
	texts[] = {"10 s","20 s","30 s","45 s"};
	default = 20;
};
class VIOC_FIRE_ORDERS_ARTY {
	title = "VIOC: Ordenes de fuego: artilleria de tu grupo (obuses, lanzacohetes, morteros)";
	values[] = {0,1,2};
	texts[] = {"No","Si (sin espera)","Si (con la espera del lobby ARTILLERY: Delay)"};
	default = 1;
};

//--- VIOC fire_orders: ordenes de fuego a la IA de tu grupo (el artillero dispara solo al punto u objetivo; mira, mapa con panel y disparar a discrecion; ver VIOC_fire_orders.sqf)
if ((missionNamespace getVariable ["VIOC_FIRE_ORDERS", 1]) > 0) then {
	player addAction ["<t color='#ffb35c'>ORDEN: Atacar donde miro</t>", {if (!isNil "VIOC_FO_fnc_quick") then {[] spawn VIOC_FO_fnc_quick}}, "", 87, false, true, "", "alive _this && {!CTI_P_PreBuilding} && {!visibleMap} && {!isNil 'VIOC_FO_fnc_avail'} && {call VIOC_FO_fnc_avail}"];
	player addAction ["<t color='#ffb35c'>ORDEN: Atacar punto (mapa)</t>", {if (!isNil "VIOC_FO_fnc_open") then {[] spawn VIOC_FO_fnc_open}}, "", 86, false, true, "", "alive _this && {!CTI_P_PreBuilding} && {!visibleMap} && {!isNil 'VIOC_FO_fnc_avail'} && {call VIOC_FO_fnc_avail}"];
	player addAction ["<t color='#ffd9a8'>Artillero: disparar a discrecion (ON)</t>", {if (!isNil "VIOC_FO_fnc_toggleFree") then {call VIOC_FO_fnc_toggleFree}}, "", 85, false, true, "", "alive _this && {!visibleMap} && {!isNil 'VIOC_FO_fnc_availMine'} && {call VIOC_FO_fnc_availMine} && {!((vehicle _this) getVariable ['vioc_fo_free', false])}"];
	player addAction ["<t color='#ffd9a8'>Artillero: disparar a discrecion (OFF)</t>", {if (!isNil "VIOC_FO_fnc_toggleFree") then {call VIOC_FO_fnc_toggleFree}}, "", 85, false, true, "", "alive _this && {!visibleMap} && {!isNil 'VIOC_FO_fnc_availMine'} && {call VIOC_FO_fnc_availMine} && {(vehicle _this) getVariable ['vioc_fo_free', false]}"];
};
